def array_concatenation_value(nums):
    left=0;right=len(nums)-1;answer=0
    while left<=right:
        if left==right:answer+=nums[left]
        else:answer+=int(str(nums[left])+str(nums[right]))
        left+=1;right-=1
    return answer

